include "circomlib/comparators.circom";
include "circomlib/bitify.circom";

template BabyJubJubSubOrderTag(isActive) {
    signal input in;
    signal output out;

    var suborder = 2736030358979909402780800718157159386076813972158567259200215660948447373041;

    // Range-check `in` to 251 bits so LessThan(251) cannot overflow.
    component rangeCheck = Num2Bits(251);
    rangeCheck.in <== in;

    component n2b = LessThan(251);
    n2b.in[0] <== in;
    n2b.in[1] <== suborder;
    // Force the comparison to hold: in < suborder.
    n2b.out === 1;

    out <== in;
}

