        component hashNotZero = IsNotZero();
        hashNotZero.in <== kytDepositSignedMessageHash;
        bt.in <== hashNotZero.out * (1 - isZeroDeposit.out);
    } else {
        bt.in <== (1 - isZeroDeposit.out);
    }
    isKytDepositCheckEnabled <== bt.out;
}

