include "circomlib/bitify.circom";
include "circomlib/comparators.circom";

template ZAccountBlackListLeafInclusionProver(depth) {
    signal input zAccountId;        // {uint24}
    signal input leaf;
    signal input merkleRoot;
    signal input pathElements[depth];

    // FIX: strict decomposition is unique modulo p, no aliasing.
    component n2b_leaf = Num2Bits_strict();
    n2b_leaf.in <== leaf;

    component is_zero[254];
    for (var i = 0; i < 254; i++) {
        is_zero[i] = IsEqual();
        is_zero[i].in[0] <== zAccountId;
        is_zero[i].in[1] <== i;
