include "circomlib/poseidon.circom";
include "circomlib/comparators.circom";

template ZAccountRenewalV1(kycExpiryPeriod) {
    signal input spendTime;
    signal input kycSignedMessageTimestamp;
    signal input kycSignedMessageSender;
    signal output kycSignedMessageHash;

    component kycSignedMessageHashInternal = Poseidon(2);
    kycSignedMessageHashInternal.inputs[0] <== kycSignedMessageSender;
    kycSignedMessageHashInternal.inputs[1] <== kycSignedMessageTimestamp;

    // FIX: reject expired certificates: spendTime <= timestamp + expiryPeriod.
    component notExpired = LessEqThan(32);
    notExpired.in[0] <== spendTime;
    notExpired.in[1] <== kycSignedMessageTimestamp + kycExpiryPeriod;
    notExpired.out === 1;

    kycSignedMessageHash <== kycSignedMessageHashInternal.out;
}

