    component noteHasher = Poseidon(2);
    noteHasher.inputs[0] <== zAccountUtxoInNullifierPubKey[0];
    noteHasher.inputs[1] <== zAccountUtxoInNullifierPubKey[1];

    // Nullifier = hash(privKey, commitment).
    component nullifierHasher = Poseidon(2);
    nullifierHasher.inputs[0] <== zAccountUtxoInNullifierPrivKey;
    nullifierHasher.inputs[1] <== noteHasher.out;

