include "circomlib/circuits/comparators.circom";

template SMTVerify(nLevels) {
    signal input key;
    signal input root;
    signal input siblings[nLevels];
    // ... other inputs elided ...

    // FIX: Num2Bits_strict additionally constrains the decomposition to be
    // the canonical one (< p), removing the aliasing so `key` has exactly one
    // valid bit representation and the path is uniquely determined.
    component n2b = Num2Bits_strict();
    n2b.in <== key;

    signal path[254];
    for (var i = 0; i < 254; i++) {
        path[i] <== n2b.out[i];
    }

    // ... tree traversal using path[] / siblings[] ...
