include "circomlib/circuits/comparators.circom";
include "circomlib/circuits/bitify.circom";

template SnippetRegisterID {
    signal input dsc_pubKey_offset, dsc_pubKey_actual_size, raw_dsc_actual_length;

    signal output dsc_pubKey_offset_in_range;

    // FIX: constrain every index to [0, 2^12) so LessEqThan(12) is well-defined
    // and the sum below cannot overflow the field.
    component checkOffset = Num2Bits(12);
    checkOffset.in <== dsc_pubKey_offset;
    component checkSize = Num2Bits(12);
    checkSize.in <== dsc_pubKey_actual_size;
    component checkLen = Num2Bits(12);
    checkLen.in <== raw_dsc_actual_length;

    signal sum;
    sum <== dsc_pubKey_offset + dsc_pubKey_actual_size;
    // sum of two 12-bit values fits in 13 bits, well below p: no overflow.
    component checkSum = Num2Bits(13);
    checkSum.in <== sum;

    dsc_pubKey_offset_in_range <== LessEqThan(13)([sum, raw_dsc_actual_length]);
    dsc_pubKey_offset_in_range === 1;
