include "circomlib/circuits/comparators.circom";

template EmailAuthMask(n) {
    signal input subject_all[n];
    signal input removed_code[n];
    signal input removed_email[n];
    signal output masked_subject_bytes[n];

    // Resolve overlap: a byte covered by the email-address match is never also
    // treated as part of the invitation code, so it is subtracted exactly once.
    signal code_only[n];
    component emailHit[n];
    for (var i = 0; i < n; i++) {
        emailHit[i] = IsZero();
        emailHit[i].in <== removed_email[i];           // 0 => this byte IS part of the email
        // keep removed_code[i] only where the email match is absent
        code_only[i] <== removed_code[i] * emailHit[i].out;
        masked_subject_bytes[i] <== subject_all[i] - code_only[i] - removed_email[i];
