Vulnerability: SHA256 result forced to zero via out-of-bounds index in ItemAtIndex

Explanation: The SHA256 templates select the final hash block with `ItemAtIndex` at position `inBlockIndex - 1`, where `inBlockIndex <-- (paddedInLength >> 9)` is a prover hint constrained only by `paddedInLength === inBlockIndex * 512`. That equation does not bound the *size* of `inBlockIndex`, so a malicious prover can choose a `paddedInLength`/`inBlockIndex` pair that makes the selection index land out of range. `ItemAtIndex` is supposed to guard the index with `LessThan(bitLength)`, but `LessThan` does not reject field elements that represent small negative numbers (e.g. `-1, -2, ..., -5`, which are `p-1, ..., p-5`): these still satisfy `lt.out === 1`. When the index matches no array position `i`, none of the `IsEqual` selectors `eqs[i]` fire, and the accumulated `out` defaults to the all-zeros value. The prover thus forces the hash output to all zeros on arbitrary inputs, breaking soundness of every template built on it (`Sha256General`, `Sha256Partial`, `Sha256Bytes`, `Sha256BytesPartial`) and the DKIM verification above them.

Fix: In `ItemAtIndex`, remove the `LessThan` guard and instead assert that exactly one selector fires: `sum(eqs[i]) === 1`. This proves the index selects exactly one in-range element and rejects any out-of-bounds / negative index. Additionally constrain `paddedInLength` to its expected bit length with `Num2Bits` so `inBlockIndex` cannot be inflated.

```circom
pragma circom 2.1.6;

include "circomlib/circuits/comparators.circom";
include "circomlib/circuits/bitify.circom";

template ItemAtIndex(maxArrayLen) {
    signal input in[maxArrayLen];
    signal input index;
    signal output out;

    component eqs[maxArrayLen];
    signal sums[maxArrayLen + 1];
    signal valAcc[maxArrayLen + 1];
    sums[0] <== 0;
    valAcc[0] <== 0;
    for (var i = 0; i < maxArrayLen; i++) {
        eqs[i] = IsEqual();
        eqs[i].in[0] <== i;
        eqs[i].in[1] <== index;
        sums[i + 1] <== sums[i] + eqs[i].out;
        valAcc[i + 1] <== valAcc[i] + eqs[i].out * in[i];
    }
    // FIX: exactly one element must be selected -> index is provably in range.
    sums[maxArrayLen] === 1;
    out <== valAcc[maxArrayLen];
}

template Sha256General(maxBlocks) {
    signal input paddedInLength;
    signal input hashChunks[maxBlocks];
    signal output out;

    // FIX: bound paddedInLength to its expected bit length (here log2(maxBlocks*512)).
    component lenBits = Num2Bits(20);
    lenBits.in <== paddedInLength;

    signal inBlockIndex;
    inBlockIndex <-- (paddedInLength >> 9);
    paddedInLength === inBlockIndex * 512;

    component select = ItemAtIndex(maxBlocks);
    for (var i = 0; i < maxBlocks; i++) { select.in[i] <== hashChunks[i]; }
    select.index <== inBlockIndex - 1;
    out <== select.out;
}

component main { public [paddedInLength] } = Sha256General(4);
```

