include "secp256k1/add.circom";
include "comparators.circom";

template EfficientECDSA() {
    var bits = 256;
    signal input s;
    signal input Tx;
    signal input Ty;
    signal input Ux;
    signal input Uy;

    signal output pubKeyX;
    signal output pubKeyY;

    // Constrain s so the s * T term cannot be bypassed (s = 0 is rejected).
    component sIsZero = IsZero();
    sIsZero.in <== s;
    sIsZero.out === 0;

    component sMultT = Secp256k1Mul();
    sMultT.scalar <== s;
    sMultT.xP <== Tx;
    sMultT.yP <== Ty;

