include "../../node_modules/circomlib/circuits/poseidon.circom";
include "../../node_modules/circomlib/circuits/comparators.circom";
include "tree.circom";

template Semaphore(nLevels) {
    signal input identityNullifier;
    signal input identityTrapdoor;
    signal input treePathIndices[nLevels];
    signal input treeSiblings[nLevels];

    signal input signalHash;
    signal input externalNullifier;
    signal input zeroValue;     // empty-leaf value used to init the tree

    signal output root;
    signal output nullifierHash;

    component calculateSecret = Poseidon(2);
    calculateSecret.inputs[0] <== identityNullifier;
    calculateSecret.inputs[1] <== identityTrapdoor;

    component calculateIdentityCommitment = Poseidon(1);
    calculateIdentityCommitment.inputs[0] <== calculateSecret.out;

    component calculateNullifierHash = Poseidon(2);
    calculateNullifierHash.inputs[0] <== externalNullifier;
    calculateNullifierHash.inputs[1] <== identityNullifier;

    // Reject the empty-leaf zeroValue so it cannot act as a phantom member.
    component isZeroLeaf = IsEqual();
    isZeroLeaf.in[0] <== calculateIdentityCommitment.out;
    isZeroLeaf.in[1] <== zeroValue;
    isZeroLeaf.out === 0;

    component inclusionProof = MerkleTreeInclusionProof(nLevels);
    inclusionProof.leaf <== calculateIdentityCommitment.out;
    for (var i = 0; i < nLevels; i++) {
        inclusionProof.siblings[i] <== treeSiblings[i];
        inclusionProof.pathIndices[i] <== treePathIndices[i];
