include "circomlib/circuits/bitify.circom";
include "circomlib/circuits/comparators.circom";

// BigMod computes div and mod such that a = b*div + mod, where a, b are
// big integers represented in k limbs of n bits each. The quotient `div`
// is range-checked with Num2Bits, but the remainder `mod` is NOT, leaving
// it under-constrained.
template BigMod(n, k) {
    assert(n <= 126);
    signal input a[2 * k];
    signal input b[k];

    signal output div[k + 1];
    signal output mod[k];

    // Witness-computed long division (hint only).
    var longdiv[2][50] = long_div(n, k, k, a, b);
    for (var i = 0; i <= k; i++) {
        div[i] <-- longdiv[0][i];
    }
    for (var i = 0; i < k; i++) {
        mod[i] <-- longdiv[1][i];
    }

    // Range check on the quotient limbs only.
    component range_checks[k + 1];
    for (var i = 0; i <= k; i++) {
        range_checks[i] = Num2Bits(n);
        range_checks[i].in <== div[i];
    }

    // mod[i] is fed straight into BigMult / BigLessThan with NO range check,
    // so a malicious prover can supply mod[i] >= 2**n and still satisfy the
    // multiplication identity, breaking the modulus invariant.
    component mul = BigMult(n, k);
    for (var i = 0; i < k; i++) { mul.a[i] <== div[i]; mul.b[i] <== b[i]; }
    // ... a === b*div + mod checked elsewhere ...
    component lt = BigLessThan(n, k);
    for (var i = 0; i < k; i++) { lt.a[i] <== mod[i]; lt.b[i] <== b[i]; }
    lt.out === 1;
}

component main = BigMod(126, 2);
```

Vulnerability: Missing range checks on the remainder limbs in BigMod

Explanation: The `BigMod` template computes a quotient `div` and remainder `mod` via the long-division hint `long_div`, then is supposed to enforce `a = b*div + mod` with `0 <= mod < b`. Each limb of the quotient `div[i]` is constrained to fit in `n` bits through `Num2Bits(n)`, but the remainder limbs `mod[i]` receive no analogous range check. The assignment `mod[i] <-- longdiv[1][i]` is only a witness hint, so a malicious prover is free to pick remainder limbs larger than `2**n`. Since the surrounding `BigMult`/`BigLessThan` arithmetic operates on limb sums, an out-of-range `mod[i]` (e.g. carrying field-sized garbage) can still satisfy the multiplication identity and the comparison, letting the prover produce a `mod` that is not the true canonical remainder. This breaks the soundness of the modulus operation for every consumer of `BigMod`.

Fix: Add `Num2Bits(n)` range-check constraints on each `mod[i]` limb, exactly as is already done for `div[i]`, so the remainder is forced into `[0, 2**n)` and cannot overflow.

```circom
pragma circom 2.0.2;

include "circomlib/circuits/bitify.circom";
include "circomlib/circuits/comparators.circom";

template BigMod(n, k) {
    assert(n <= 126);
    signal input a[2 * k];
    signal input b[k];

    signal output div[k + 1];
    signal output mod[k];

    var longdiv[2][50] = long_div(n, k, k, a, b);
    for (var i = 0; i <= k; i++) {
        div[i] <-- longdiv[0][i];
    }
    for (var i = 0; i < k; i++) {
        mod[i] <-- longdiv[1][i];
    }

    // Range check the quotient limbs.
    component div_range_checks[k + 1];
    for (var i = 0; i <= k; i++) {
        div_range_checks[i] = Num2Bits(n);
        div_range_checks[i].in <== div[i];
    }

    // FIX: also range check every remainder limb so mod[i] < 2**n.
    component mod_range_checks[k];
    for (var i = 0; i < k; i++) {
        mod_range_checks[i] = Num2Bits(n);
        mod_range_checks[i].in <== mod[i];
    }

    component mul = BigMult(n, k);
    for (var i = 0; i < k; i++) { mul.a[i] <== div[i]; mul.b[i] <== b[i]; }
    component lt = BigLessThan(n, k);
    for (var i = 0; i < k; i++) { lt.a[i] <== mod[i]; lt.b[i] <== b[i]; }
    lt.out === 1;
}

component main = BigMod(126, 2);
