pragma circom 2.1.8;

include "circomlib/circuits/poseidon.circom";
include "merkleTree.circom";

// CreditVerifier proves that a credit-note commitment H(nullifier, secret,
// pubCreditType) is in the credit Merkle tree, and reveals a matching
// pubNullifierHash so the credit can be spent. Its only public inputs are
// pubRoot, pubCreditType and pubNullifierHash -- nothing binds the proof to
// the spender or to a specific spend intent.
template CreditVerifier(levels) {
    // Private witness.
    signal input nullifier;
    signal input secret;
    signal input pathElements[levels];
    signal input pathIndices[levels];

    // Public inputs.
    signal input pubRoot;
    signal input pubCreditType;
    signal input pubNullifierHash;

    // Recompute and reveal the nullifier hash.
    component nh = Poseidon(1);
    nh.inputs[0] <== nullifier;
    nh.out === pubNullifierHash;

    // Commitment = H(nullifier, secret, creditType).
    component commit = Poseidon(3);
    commit.inputs[0] <== nullifier;
    commit.inputs[1] <== secret;
    commit.inputs[2] <== pubCreditType;

    // Merkle inclusion of the commitment under pubRoot.
    component tree = MerkleTreeChecker(levels);
    tree.leaf <== commit.out;
    tree.root <== pubRoot;
    for (var i = 0; i < levels; i++) {
        tree.pathElements[i] <== pathElements[i];
        tree.pathIndices[i] <== pathIndices[i];
    }
}

component main { public [pubRoot, pubCreditType, pubNullifierHash] } = CreditVerifier(3);
```

Vulnerability: CreditNoteProof is replayable because it is not bound to a spender

Explanation: `CreditVerifier` is a faithful proof of knowledge: it shows the prover knows a `(nullifier, secret)` whose commitment `H(nullifier, secret, pubCreditType)` is in the credit Merkle tree, and it reveals `pubNullifierHash`. However, none of its constraints reference the spender or the call that consumes the credit; the only public outputs are `pubRoot`, `pubCreditType`, and `pubNullifierHash`. The on-chain `_verifyProof` in `ArianeeIssuerProxy` accepts this proof as a plain transaction argument without checking it against `msg.sender` or an intent hash. Consequently, anyone who observes a valid `CreditNoteProof` in the mempool can copy the identical proof, front-run the legitimate spender, burn the same nullifier, and steal the credit. The flaw is a missing input binding: the proof is not tied to a spender-controlled value.

Fix: Introduce a spender-bound public input `pubIntentHash` into `CreditVerifier` (mirroring the `pubIntentHash` already used by `OwnershipVerifier`) and constrain it into the statement, then have `ArianeeIssuerProxy`/`ArianeeCreditNotePool` re-check the caller's intent against it. Because a front-runner cannot reproduce the legitimate caller's intent, the proof can no longer be replayed.

```circom
pragma circom 2.1.8;

include "circomlib/circuits/poseidon.circom";
include "merkleTree.circom";

template CreditVerifier(levels) {
    signal input nullifier;
    signal input secret;
    signal input pathElements[levels];
    signal input pathIndices[levels];

    signal input pubRoot;
    signal input pubCreditType;
    signal input pubNullifierHash;
    // FIX: spender-bound public input. Bound by the on-chain caller's intent.
    signal input pubIntentHash;

    component nh = Poseidon(1);
    nh.inputs[0] <== nullifier;
    nh.out === pubNullifierHash;

    component commit = Poseidon(3);
    commit.inputs[0] <== nullifier;
    commit.inputs[1] <== secret;
    commit.inputs[2] <== pubCreditType;

    component tree = MerkleTreeChecker(levels);
    tree.leaf <== commit.out;
    tree.root <== pubRoot;
    for (var i = 0; i < levels; i++) {
        tree.pathElements[i] <== pathElements[i];
        tree.pathIndices[i] <== pathIndices[i];
    }

    // FIX: bind the proof to the caller's intent so it cannot be replayed by a
    // front-runner. The squared term forces pubIntentHash into the constraint
    // system; ArianeeIssuerProxy must check it equals the caller's intent.
    signal intentBinding;
    intentBinding <== pubIntentHash * pubIntentHash;
}

component main { public [pubRoot, pubCreditType, pubNullifierHash, pubIntentHash] } = CreditVerifier(3);
```

