pragma circom 2.1.8;

include "circomlib/circuits/poseidon.circom";

// OwnershipVerifier proves knowledge of the (R, S, V) signature triple whose
// Poseidon hash equals the public pubCommitmentHash. The signature is static
// per issuer and tokenId is never fed into the commitment, so one commitment
// can be reused across every token an issuer controls.
template OwnershipVerifier() {
    // Private: issuer's static (R, S, V) signature components.
    signal input sig[3];

    // Public.
    signal input pubCommitmentHash;
    signal input pubIntentHash;
    signal input pubNonce;

    component commitmentHasher = Poseidon(3);
    commitmentHasher.inputs[0] <== sig[0];
    commitmentHasher.inputs[1] <== sig[1];
    commitmentHasher.inputs[2] <== sig[2];

    commitmentHasher.out === pubCommitmentHash;

    // pubIntentHash / pubNonce bind the call but NOT the token identity.
    signal intentBinding <== pubIntentHash * pubNonce;
}

component main { public [pubCommitmentHash, pubIntentHash, pubNonce] } = OwnershipVerifier();
```

Vulnerability: Issuer commitments are reusable across tokens, deanonymizing issuers

Explanation: `OwnershipVerifier` computes `commitmentHasher = Poseidon(3)` over the static per-issuer signature `sig[0..2]` and constrains it to equal `pubCommitmentHash`. The token identity (`tokenId`) is never an input to the hash and nothing in the circuit forces distinct tokens to use distinct commitments. Since `sig` is constant for an issuer, the same `pubCommitmentHash` is valid for every token that issuer owns, turning the commitment into a stable per-issuer identifier. The moment any single token is linked to an issuer, all other tokens sharing that commitment are linked as well, leaking the entire set of assets and activity controlled by that issuer and defeating the privacy goal. This is a missing-input-binding problem: per-token data is absent from the committed statement.

Fix: Bind `tokenId` (and any other per-token data) into the commitment so commitments cannot be reused across tokens: extend the hasher to `Poseidon(4)` with `tokenId` as the fourth input, add `tokenId` as a public input, and verify it against the token being operated on in `ArianeeIssuerProxy`.

```circom
pragma circom 2.1.8;

include "circomlib/circuits/poseidon.circom";

template OwnershipVerifier() {
    signal input sig[3];

    signal input pubCommitmentHash;
    signal input pubIntentHash;
    signal input pubNonce;
    // FIX: per-token value bound into the commitment.
    signal input tokenId;

    component commitmentHasher = Poseidon(4);
    commitmentHasher.inputs[0] <== sig[0];
    commitmentHasher.inputs[1] <== sig[1];
    commitmentHasher.inputs[2] <== sig[2];
    commitmentHasher.inputs[3] <== tokenId;

    commitmentHasher.out === pubCommitmentHash;

    signal intentBinding <== pubIntentHash * pubNonce;
}

// tokenId is now public and must be checked against the operated token on-chain.
component main { public [pubCommitmentHash, pubIntentHash, pubNonce, tokenId] } = OwnershipVerifier();
```

