    signal input nonceIndex;
    signal input nonceLength;   // user-controlled, NOT range-checked
    signal output nonce[maxNonceLength];

    // RevealSubstring internally does LessThan(log2Ceil(maxNonceLength+1)) on
    // nonceLength; an out-of-range nonceLength flips the comparison.
    component reveal = RevealSubstring(maxPayloadLength, maxNonceLength, 0);
    reveal.in <== payload;
    reveal.startIndex <== nonceIndex;
    reveal.revealLength <== nonceLength;
    nonce <== reveal.out;
}

component main = ExtractNonce(1024, 44);
```

Vulnerability: Length input fed to LessThan is not range-checked, making the extracted nonce non-deterministic

Explanation: `ExtractNonce` passes the prover-supplied `nonceLength` straight into zkemail's `RevealSubstring`, which internally compares `nonceLength` against a bound using `LessThan(log2Ceil(maxNonceLength + 1))`. `LessThan` only behaves correctly when its inputs fit in the configured bit width; nothing constrains `nonceLength` to that width. A malicious prover can therefore choose a `nonceLength` larger than the comparator's bit budget so the comparison returns the wrong bit, causing `RevealSubstring` to emit a nonce with spurious leading or trailing zero bytes. The same missing-range-check pattern applies to `issLength`, `audLength`, and `subLength`. Additionally, the extracted nonce bytes are not constrained to the base64url alphabet, so two distinct byte sequences can map to the same decoded value, and the packed nonce is not bounded below the BN254 prime, allowing field overflow collisions. All three issues make the derived field inputs non-deterministic / under-constrained.

Fix: Range-check `nonceLength` (and the analogous `issLength`/`audLength`/`subLength`) with `Num2Bits` so it provably fits the bit width assumed by the internal `LessThan` before it is used. Additionally validate that each nonce byte lies in the base64url alphabet and add an explicit range check (`AssertFitsBinary`) on the decoded bytes so the packed nonce cannot overflow the field.

```circom
pragma circom 2.1.6;

include "circomlib/circuits/bitify.circom";
include "circomlib/circuits/comparators.circom";
include "@zk-email/circuits/utils/array.circom";

template ExtractNonce(maxPayloadLength, maxNonceLength) {
    signal input payload[maxPayloadLength];
    signal input nonceIndex;
    signal input nonceLength;
    signal output nonce[maxNonceLength];

    // FIX: range-check nonceLength so it fits the bit width that the internal
    // LessThan comparator assumes (log2Ceil(maxNonceLength + 1) bits). This
    // prevents the prover from flipping the comparison via an oversized value.
    var nb = 6; // >= log2Ceil(maxNonceLength + 1) for maxNonceLength = 44
    component lenBits = Num2Bits(nb);
    lenBits.in <== nonceLength;

    component reveal = RevealSubstring(maxPayloadLength, maxNonceLength, 0);
    reveal.in <== payload;
    reveal.startIndex <== nonceIndex;
    reveal.revealLength <== nonceLength;
    nonce <== reveal.out;

    // FIX (sketch): each emitted nonce byte must lie in the base64url alphabet
    // and be a valid byte, removing alphabet ambiguity and field overflow.
    component byteBits[maxNonceLength];
    for (var i = 0; i < maxNonceLength; i++) {
        byteBits[i] = Num2Bits(8);
        byteBits[i].in <== nonce[i];
    }
}

component main = ExtractNonce(1024, 44);
```

