    component eqUpper = IsEqual();
    component ltLower = LessThan(128);
    ltUpper.in[0] <== upperA.out; ltUpper.in[1] <== upperB.out;
    eqUpper.in[0] <== upperA.out; eqUpper.in[1] <== upperB.out;
    ltLower.in[0] <== lowerA.out; ltLower.in[1] <== lowerB.out;

