include "circomlib/circuits/bitify.circom";
include "circomlib/circuits/comparators.circom";

template BigLessThan() {
    signal input in[2];
    signal output out;

    // FIX: Num2Bits_strict forces in[i] < p, so non-canonical (aliased) inputs
    // larger than the field modulus are rejected.
    component n2bA = Num2Bits_strict();
    component n2bB = Num2Bits_strict();
    n2bA.in <== in[0];
    n2bB.in <== in[1];

    component lowerA = Bits2Num(128);
    component upperA = Bits2Num(126);
    component lowerB = Bits2Num(128);
    component upperB = Bits2Num(126);
    for (var i = 0; i < 128; i++) {
        lowerA.in[i] <== n2bA.out[i];
        lowerB.in[i] <== n2bB.out[i];
    }
    for (var i = 0; i < 126; i++) {
        upperA.in[i] <== n2bA.out[i + 128];
        upperB.in[i] <== n2bB.out[i + 128];
    }

    component ltUpper = LessThan(128);
    component eqUpper = IsEqual();
    component ltLower = LessThan(128);
    ltUpper.in[0] <== upperA.out; ltUpper.in[1] <== upperB.out;
    eqUpper.in[0] <== upperA.out; eqUpper.in[1] <== upperB.out;
    ltLower.in[0] <== lowerA.out; ltLower.in[1] <== lowerB.out;

    out <== ltUpper.out + eqUpper.out * ltLower.out;
}

