pragma circom 2.1.3;

include "circomlib/comparators.circom";

// Base64DecodedLength(maxN): given an encoded length `n`, return the number of
// bytes the base64 payload decodes to. From aptos-labs/keyless-zk-proofs.
template Base64DecodedLength(maxN) {
    var max_q = (3 * maxN) \ 4;

    signal input n;
    signal output decoded_len;

    signal q <-- 3*n \ 4;
    signal r <-- 3*n % 4;

    // Euclidean division 3*n = 4*q + r is enforced...
    3*n - 4*q - r === 0;

    signal r_correct_reminder <== LessThan(2)([r, 4]);
    r_correct_reminder === 1;

    signal q_correct_quotient <== LessThan(252)([q, max_q]);
    q_correct_quotient === 1;

    // ...but `decoded_len` is declared as a circuit output and NEVER assigned
    // or constrained. The line `decoded_len <== q + reducer;` was commented out.
}

component main = Base64DecodedLength(8);
```

Vulnerability: Output signal `decoded_len` is declared but never constrained

Explanation: `Base64DecodedLength` declares `signal output decoded_len` but the template body never assigns or constrains it. The body only constrains `q` and `r` as the quotient/remainder of `3*n` divided by `4` (`3*n - 4*q - r === 0`) plus two `LessThan` bound checks; the line that would have set `decoded_len <== q` is commented out. Because `decoded_len` is a circuit output with no `<==` or `===` tying it to anything, it is a free variable at the R1CS level: a malicious prover can pick ANY value for it during witness generation and every constraint still holds. The caller binds `ascii_payload_len <== Base64DecodedLength(maxJWTPayloadLen)(b64_payload_len)` and feeds `ascii_payload_len` into `HashBytesToFieldWithLen(...)` as the length of the hashed JWT-payload region. By choosing an arbitrary `decoded_len`, the prover breaks the binding between the base64-decoded payload and the hashed length, defeating the soundness of the JWT-payload commitment.

Fix: Assign the output with a real constraint so it equals the internally-enforced quotient `q` (which matches the Euclidean division `3*n === 4*q + r`). Also strengthen the bound checks to explicit `Num2Bits` range checks as done in the fix.

```circom
pragma circom 2.1.3;

include "circomlib/comparators.circom";
include "circomlib/bitify.circom";

template Base64DecodedLength(maxN) {
    var max_q = (3 * maxN) \ 4;
    var MAX_QUO_BITS = nbits(max_q);

    signal input n;
    signal output decoded_len;

    signal q <-- 3*n \ 4;
    signal r <-- 3*n % 4;

    3*n - 4*q - r === 0;

    // Explicit range checks instead of LessThan-on-unbounded-inputs.
    _ <== Num2Bits(2)(r);            // r in [0,4)
    _ <== Num2Bits(MAX_QUO_BITS)(q); // q bounded by max_q

    // Constrain the output: decoded_len is exactly the quotient.
    decoded_len <== q;
}

component main = Base64DecodedLength(8);
```

