include "circomlib/comparators.circom";

// Checks that the current node's `depth` lies strictly above the leaf layer.
// From banyancomputer/hot-proofs-blake3-circom (circuits/blake3_nova.circom).
template Blake3NovaTreePath_CheckDepth() {
    signal input depth;
    signal input leaf_depth;
    signal output is_parent;

    // `depth` and `leaf_depth` are free field elements and are fed directly
    // into 8-bit comparators with NO range check beforehand.
