    signal input range;
    signal input value;
    signal output out;
    component rc = Num2Bits(n); rc.in <== index;
    component lt = LessThan(n);
    lt.in[0] <== index;
    lt.in[1] <== range;
    out <== lt.out * value;
}

// Right shift by 1 with full constraints: range-checks `in` and rebuilds
// the value from bits[1..N-1].
template RShift1(N) {
    signal input in;
    signal output out;
    component n2b = Num2Bits(N);
    n2b.in <== in;
    component b2n = Bits2Num(N - 1);
    for (var i = 0; i < N - 1; i++) {
        b2n.in[i] <== n2b.out[i + 1];
    }
    out <== b2n.out;
}

template ExtractStringFromPoint() {
    var N = 31;
    signal input pointAsBytes[N];
    signal output stringAsBytes[N - 1];

    // Constrained shift: length is now deterministically bound to pointAsBytes[0].
    signal shiftedFirstByte <== RShift1(8)(pointAsBytes[0]);
