    sufficientBalanceChecker.in[0] <== balance;
    sufficientBalanceChecker.in[1] <== withdrawnBalance;
    sufficientBalanceChecker.out === 1;

    component remainingCoinHasher = MiMCSponge(2, 220, 1);
    remainingCoinHasher.ins[0] <== balance - withdrawnBalance;
    remainingCoinHasher.ins[1] <== remainingCoinSalt;
    remainingCoinHasher.k <== 0;
    remainingCoin <== remainingCoinHasher.outs[0];
}

component main {public [withdrawnBalance]} = Spend();
```

Vulnerability: Missing range checks on GreaterEqThan inputs allow balance check to be bypassed

Explanation: The sufficiency check `balance >= withdrawnBalance` is enforced with `GreaterEqThan(252)` and `sufficientBalanceChecker.out === 1`. `GreaterEqThan(N)` internally does `LessThan(N+1)` on `in[0] + 2^N - in[1]` and is only correct when BOTH inputs are already known to be less than `2^N`; it has no internal range constraints. Here `balance` and `withdrawnBalance` are arbitrary BN254 field elements and are never constrained to fit in 252 bits. A malicious prover can pick `withdrawnBalance` close to the field prime (e.g. `withdrawnBalance = 21888242871839275222246405745257275088548364400416034343698204186575808495579`) with `balance = 0`, so that the internal `in[0] + 2^252 - in[1]` wraps modulo the prime and `GreaterEqThan` returns `1` even though the intended unsigned comparison `0 >= withdrawnBalance` is false. The `coinHasher` / `remainingCoinHasher` commitments still compute fine (`remainingCoin` just commits `balance - withdrawnBalance`, which also wraps), so the prover produces a fully valid `Spend` proof for a withdrawal where `balance < withdrawnBalance` — letting them withdraw more than they actually burned and drain funds.

Fix: Range-check both comparator inputs to be below `2^maxAmountBits` before comparing, well under the 252-bit overflow boundary. Replace the raw `GreaterEqThan(252)` with an `AssertGreaterEqThan(maxAmountBits)` that first decomposes each input with `Num2Bits(maxAmountBits)` (forcing `balance`, `withdrawnBalance < 2^maxAmountBits`) and then performs the comparison, and parameterize `Spend(maxAmountBits)` instantiated as `Spend(200)`.

```circom
pragma circom 2.2.2;

include "circuits/comparators.circom";
include "circuits/bitify.circom";
include "circuits/mimcsponge.circom";

// Range-checks both inputs to fit in `n` bits, then asserts in[0] >= in[1].
template AssertGreaterEqThan(n) {
    signal input in[2];
    // Constrain both operands to be < 2^n so GreaterEqThan is sound.
    component lo = Num2Bits(n);
    component hi = Num2Bits(n);
    lo.in <== in[0];
    hi.in <== in[1];

    component ge = GreaterEqThan(n);
    ge.in[0] <== in[0];
    ge.in[1] <== in[1];
    ge.out === 1;
}

template Spend(maxAmountBits) {
    signal input balance;
    signal input salt;
    signal output coin;

    component coinHasher = MiMCSponge(2, 220, 1);
    coinHasher.ins[0] <== balance;
    coinHasher.ins[1] <== salt;
    coinHasher.k <== 0;
    coin <== coinHasher.outs[0];

    signal input withdrawnBalance;
    signal input remainingCoinSalt;
    signal output remainingCoin;

    // balance and withdrawnBalance are now forced into maxAmountBits range.
    component sufficientBalanceChecker = AssertGreaterEqThan(maxAmountBits);
    sufficientBalanceChecker.in[0] <== balance;
    sufficientBalanceChecker.in[1] <== withdrawnBalance;

    component remainingCoinHasher = MiMCSponge(2, 220, 1);
    remainingCoinHasher.ins[0] <== balance - withdrawnBalance;
    remainingCoinHasher.ins[1] <== remainingCoinSalt;
    remainingCoinHasher.k <== 0;
    remainingCoin <== remainingCoinHasher.outs[0];
}

component main {public [withdrawnBalance]} = Spend(200);
```

