            inflow_erc20[i].note_token_addr[j] <== spending_note_token_addr[j];
            inflow_erc20[i].note_erc20[j] <== spending_note_erc20[j];
        }

        outflow_erc20[i] = ERC20Sum(nOut);
        outflow_erc20[i].addr <== spending_note_token_addr[i];
        for (var j = 0; j < nOut; j++) {
