Vulnerability: ERC-20 balance only checked for token addresses present in the inputs, allowing minting of arbitrary output tokens

Explanation: The balance check loops over the `nIn` input (spend) notes and, for each `spending_note_token_addr[i]`, builds an inflow sum and an outflow sum with `ERC20Sum`. The outflow component is keyed on an input address — `outflow_erc20[i].addr <== spending_note_token_addr[i]` — so `ERC20Sum` only accumulates output notes whose token address equals one of the input addresses; every output note carrying a token address that does NOT appear in any input note contributes `0` to every outflow sum. The constraint `inflow_erc20[i].out === outflow_erc20[i].out` therefore only enforces conservation per input-set address, and never constrains output notes with brand-new token addresses at all. A malicious prover can add an output note for an arbitrary ERC-20 address that is absent from all inputs, give it any value, and the proof still verifies because that token is invisible to the sum check — letting the attacker mint/drain funds of tokens that were never deposited.

Fix: Make the conservation check cover every token address that appears in the outputs, not just those in the inputs. Concretely, require that each output note's token address matches some input note's address (reject outputs introducing new token addresses), or compute and compare inflow/outflow sums keyed on the union of input and output addresses. Below, each output address is constrained to equal at least one spend-note address so no unaccounted token can be created.

```circom
pragma circom 2.0.0;

include "circuits/comparators.circom";

template ERC20Sum(n) {
    signal input addr;
    signal input note_token_addr[n];
    signal input note_erc20[n];
    signal output out;

    signal partial[n + 1];
    component eq[n];
    partial[0] <== 0;
    for (var i = 0; i < n; i++) {
        eq[i] = IsEqual();
        eq[i].in[0] <== addr;
        eq[i].in[1] <== note_token_addr[i];
        partial[i + 1] <== partial[i] + eq[i].out * note_erc20[i];
    }
    out <== partial[n];
}

template ZkTransaction(addrBits, nIn, nOut) {
    signal input spending_note_token_addr[nIn];
    signal input spending_note_erc20[nIn];
    signal input new_note_token_addr[nOut];
    signal input new_note_erc20[nOut];

    // 1) Forbid output notes whose token address is absent from every input.
    component out_eq[nOut][nIn];
    signal out_match[nOut][nIn + 1];
    for (var o = 0; o < nOut; o++) {
        out_match[o][0] <== 0;
        for (var i = 0; i < nIn; i++) {
            out_eq[o][i] = IsEqual();
            out_eq[o][i].in[0] <== new_note_token_addr[o];
            out_eq[o][i].in[1] <== spending_note_token_addr[i];
            out_match[o][i + 1] <== out_match[o][i] + out_eq[o][i].out;
        }
        // Each output token address must equal at least one input address.
        component nonzero = IsZero();
        nonzero.in <== out_match[o][nIn];
        nonzero.out === 0;
    }

    // 2) Per-address conservation now covers all output tokens.
    component inflow_erc20[nIn];
    component outflow_erc20[nIn];
    for (var i = 0; i < nIn; i++) {
        inflow_erc20[i] = ERC20Sum(nIn);
        inflow_erc20[i].addr <== spending_note_token_addr[i];
        for (var j = 0; j < nIn; j++) {
            inflow_erc20[i].note_token_addr[j] <== spending_note_token_addr[j];
            inflow_erc20[i].note_erc20[j] <== spending_note_erc20[j];
        }

        outflow_erc20[i] = ERC20Sum(nOut);
        outflow_erc20[i].addr <== spending_note_token_addr[i];
        for (var j = 0; j < nOut; j++) {
            outflow_erc20[i].note_token_addr[j] <== new_note_token_addr[j];
            outflow_erc20[i].note_erc20[j] <== new_note_erc20[j];
        }

        inflow_erc20[i].out === outflow_erc20[i].out;
    }
}

component main = ZkTransaction(48, 1, 1);
```

