pragma circom 2.0.0;

include "circuits/eddsaposeidon.circom";

// Proves the prover owns a note by verifying an EdDSA signature over the
// note hash with the owner's public key.
template OwnershipProof() {
    signal input note;
    signal input pub_key[2];
    signal input sig_r8[2];
    signal input sig_s;

    component eddsa = EdDSAPoseidonVerifier();
    // VULNERABLE: verification is turned off.
    eddsa.enabled <== 0;
    eddsa.Ax <== pub_key[0];
    eddsa.Ay <== pub_key[1];
    eddsa.R8x <== sig_r8[0];
    eddsa.R8y <== sig_r8[1];
    eddsa.S <== sig_s;
    eddsa.M <== note;
}

component main = OwnershipProof();
```

Vulnerability: EdDSA signature verification disabled via `enabled <== 0`, so ownership is never proven

Explanation: `OwnershipProof` wires the note hash, public key and signature into circomlib's `EdDSAPoseidonVerifier`, which is the intended ownership check. `EdDSAPoseidonVerifier` gates all of its signature constraints behind its `enabled` input: when `enabled` is `0`, every internal verification constraint is multiplied by `enabled` and becomes `0 === 0`, i.e. trivially satisfied for ANY values of `Ax`, `Ay`, `R8x`, `R8y`, `S` and `M`. Here `eddsa.enabled <== 0`, so the circuit performs no signature verification at all. An attacker who does not own the note can supply the victim's `pub_key` together with a completely fabricated, non-existent signature (`sig_r8`, `sig_s`) and still produce a valid proof, defeating the ownership guarantee and letting them spend notes they do not own.

Fix: Enable the verifier by constraining its `enabled` signal to `1` so the EdDSA constraints are actually enforced.

```circom
pragma circom 2.0.0;

include "circuits/eddsaposeidon.circom";

template OwnershipProof() {
    signal input note;
    signal input pub_key[2];
    signal input sig_r8[2];
    signal input sig_s;

    component eddsa = EdDSAPoseidonVerifier();
    // Turn verification ON so the signature constraints are enforced.
    eddsa.enabled <== 1;
    eddsa.Ax <== pub_key[0];
    eddsa.Ay <== pub_key[1];
    eddsa.R8x <== sig_r8[0];
    eddsa.R8y <== sig_r8[1];
    eddsa.S <== sig_s;
    eddsa.M <== note;
}

component main = OwnershipProof();
```

