pub fn configure<F: FieldExt>(
    cs: &mut ConstraintSystem<F>,
    cb: &mut ConstraintBuilder<F>,
) -> Self {
    let advice_column = cs.advice_column();
    let binary_column = Self(advice_column);
    // Constrain the column to be Boolean: 1 - (v OR NOT v) == 0.
    let v = binary_column.current();
    cb.assert_zero(
        "binary column is Boolean",
        Query::one() - v.clone().or(!v).into(),
    );
    binary_column
}
