Vulnerability: Under-constrained outputs in reduce_sym

Explanation: `reduce_sym` allocates its `output_expr`, `output_env`, and `output_cont` directly from the prover witness and is supposed to enforce that they equal exactly one of the ten possible results implied by the symbol-lookup branch conditions (self-evaluating symbol, matched/unmatched variable binding, recursive binding, missing env, missing binding, error, etc.). In this version the branch predicates are computed but the constraints linking them to the witnessed outputs are weak or missing, so under certain conditions the outputs are unconstrained. A malicious prover can therefore witness arbitrary `output_expr`/`output_env`/`output_cont` values, breaking the soundness of symbol reduction.

Fix: Refactor `reduce_sym` into three explicit phases: (1) compute every branch condition and the corresponding candidate output value, (2) assign a predicate that is true exactly when each candidate should be returned, and (3) add `implies!` constraints enforcing each output to equal its candidate whenever its predicate holds. This makes every one of the ten outputs constrained, matching the Rust specification while reducing total constraints.

```rust
fn reduce_sym<F: LurkField, CS: ConstraintSystem<F>>(
    cs: &mut CS,
    expr: &AllocatedPtr<F>,
    env: &AllocatedPtr<F>,
    cont: &AllocatedContPtr<F>,
    not_dummy: &Boolean,
    witness: &Option<Witness<F>>,
    // ...
    g: &GlobalAllocations<F>,
) -> Result<(/* ... */), SynthesisError> {
    let output_expr = AllocatedPtr::alloc_ptr(&mut cs.namespace(|| "output_expr"), store, || {
        witness.as_ref().map(|w| &w.prethunk_output_expr).ok_or(SynthesisError::AssignmentMissing)
    })?;
    let output_env = AllocatedPtr::alloc_ptr(&mut cs.namespace(|| "output_env"), store, || {
        witness.as_ref().map(|w| &w.prethunk_output_env).ok_or(SynthesisError::AssignmentMissing)
    })?;
    let output_cont = AllocatedContPtr::alloc_cont_ptr(&mut cs.namespace(|| "output_cont"), store, || {
        witness.as_ref().map(|w| &w.prethunk_output_cont).ok_or(SynthesisError::AssignmentMissing)
    })?;

    // (1) Equality predicates between the witnessed outputs and each candidate.
    let output_expr_is_expr = equal_t!(cs, &output_expr, expr)?;
    let output_env_is_env = equal_t!(cs, &output_env, env)?;
    let output_cont_is_cont = equal_t!(cs, &output_cont, cont)?;
    let output_cont_is_error = equal_t!(cs, &output_cont, &g.error_ptr)?;
    let output_expr_is_val = equal_t!(cs, &output_expr, &val)?;
    let output_env_is_smaller_env = equal_t!(cs, &output_env, &smaller_env)?;
    let output_cont_is_lookup = equal_t!(cs, &output_cont, &lookup_continuation)?;
    let output_expr_is_val_to_use = equal_t!(cs, &output_expr, &val_to_use)?;
    let output_env_is_env_to_use = equal_t!(cs, &output_env, &env_to_use)?;

    // (2) Predicates describing which candidate each output should equal.
    let output_expr_should_be_expr = or!(cs, &needed_env_missing, &sym_is_self_evaluating,
        &needed_binding_missing, &with_sym_binding_unmatched, &with_cons_binding_unmatched)?;
    let output_expr_should_be_val = with_sym_binding_matched.clone();
    let output_expr_should_be_val_to_use = with_cons_binding_matched.clone();
    let output_env_should_be_env = or!(cs, &needed_binding_missing, &needed_env_missing,
        &sym_is_self_evaluating, &with_sym_binding_matched, &with_cons_binding_matched)?;
    let output_env_should_be_smaller_env = with_sym_binding_unmatched;
    let output_env_should_be_env_to_use = with_cons_binding_unmatched_new_lookup;
    let output_cont_should_be_cont = or!(cs, &sym_is_self_evaluating, &with_sym_binding_matched,
        &with_sym_binding_unmatched_old_lookup, &with_cons_binding_matched,
        &with_cons_binding_unmatched_old_lookup)?;
    let output_cont_should_be_error = or!(cs, &with_other_binding, &needed_env_missing,
        &needed_binding_missing)?;

    // (3) Enforce each output equals its candidate when its predicate holds.
    implies!(cs, &output_expr_should_be_expr, &output_expr_is_expr);
    implies!(cs, &output_expr_should_be_val, &output_expr_is_val);
    implies!(cs, &output_expr_should_be_val_to_use, &output_expr_is_val_to_use);
    implies!(cs, &output_cont_should_be_error, &output_expr_is_expr);
    implies!(cs, &output_env_should_be_env, &output_env_is_env);
    implies!(cs, &output_env_should_be_smaller_env, &output_env_is_smaller_env);
    implies!(cs, &output_env_should_be_env_to_use, &output_env_is_env_to_use);
    implies!(cs, &output_cont_should_be_error, &output_env_is_env);
    implies!(cs, &output_cont_should_be_cont, &output_cont_is_cont);
    implies!(cs, &output_cont_should_be_error, &output_cont_is_error);
    implies!(cs, &lookup_continuation_not_dummy, &output_cont_is_lookup);

    let apply_cont_bool = or!(cs, &with_cons_binding_matched, &with_sym_binding_matched,
                              &sym_is_self_evaluating)?;
    let apply_cont_num = boolean_num!(cs, &apply_cont_bool)?;
