    for opening in opened_values.chips.iter() {
        challenger.observe(builder, opening.global_cumulative_sum);
        challenger.observe(builder, opening.local_cumulative_sum);
    }

    let alpha = challenger.sample_ext(builder);
    challenger.observe_commitment(builder, *quotient_commit);
    let zeta = challenger.sample_ext(builder);

    // ... build prep/main/perm/quotient mats from opened_values.chips ...
}
