DivideReturnStruct exec_DoDiv(ExecContext& ctx, ValU32Struct arg0, ValU32Struct arg1_0,
                              Val arg2_0, Val arg3, BoundLayout<DoDivLayout> layout4) {
  auto [x5, x6, x7, x8] = INVOKE_EXTERN(ctx, divide, arg0.low, arg0.high,
                                        arg1_0.low, arg1_0.high, (arg2_0 + (arg3 * Val(2))));
  NondetRegStruct x9  = exec_NondetReg(ctx, x5, LAYOUT_LOOKUP(layout4, quotLow));
  NondetRegStruct x10 = exec_NondetReg(ctx, x6, LAYOUT_LOOKUP(layout4, quotHigh));
  ValU32Struct x11 = ValU32Struct{ .low = x9._super, .high = x10._super };
  NondetU16RegStruct x12 = exec_NondetU16Reg(ctx, x7, LAYOUT_LOOKUP(layout4, remLow));
  NondetU16RegStruct x13 = exec_NondetU16Reg(ctx, x8, LAYOUT_LOOKUP(layout4, remHigh));
  ValU32Struct x14 = ValU32Struct{ .low = x12._super._super, .high = x13._super._super };

  MultiplyAccumulateStruct x15 = exec_MultiplyAccumulate(ctx, x11, arg1_0, x14,
      MultiplySettingsStruct{ .aSigned = arg2_0, .bSigned = arg2_0, .cSigned = arg2_0 },
      LAYOUT_LOOKUP(layout4, mul));
  EQZ((x15.outLow.low  - arg0.low),  "...AssertEqU32...");
  EQZ((x15.outLow.high - arg0.high), "...AssertEqU32...");

  NondetRegStruct x23 = exec_IsZero(ctx, (arg1_0.low + arg1_0.high), LAYOUT_LOOKUP(layout4, isZero));

  if (to_size_t(x23._super)) {
    // Division by zero: RISC-V requires quotient = 0xFFFFFFFF and remainder = numerator.
    EQZ((x11.low  - Val(0xffff)), "div-by-zero: quotient low must be 0xFFFF");
    EQZ((x11.high - Val(0xffff)), "div-by-zero: quotient high must be 0xFFFF");
    EQZ((x12._super._super - arg0.low),  "...AssertEqU32...");
    EQZ((x13._super._super - arg0.high), "...AssertEqU32...");
  } else {
    // Non-zero denominator: enforce STRICT |rem| < |denom| AND a fixed remainder sign,
    // making the (quot, rem) pair unique.
